function BookCoverPasteRollerMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and BookCoverPasteRollerMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and BookCoverPasteRollerMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and BookCoverPasteRollerMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and BookCoverPasteRollerMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and BookCoverPasteRollerMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and BookCoverPasteRollerMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and BookCoverPasteRollerMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and BookCoverPasteRollerMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #BookCoverPasteRollerMaker.buildings==0 then return false,"Potrebna valjarna delavnica" end; if not BookCoverPasteRollerMaker.maker then return false,"Potreben valjar" end; return true end
function BookCoverPasteRollerMaker.make(pt,qty) qty=qty or 1; local ok,e=BookCoverPasteRollerMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then BookCoverPasteRollerMaker.ironStock=BookCoverPasteRollerMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then BookCoverPasteRollerMaker.bronzeStock=BookCoverPasteRollerMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then BookCoverPasteRollerMaker.woodStock=BookCoverPasteRollerMaker.woodStock-d.woodCost*qty end; if d.leatherCost then BookCoverPasteRollerMaker.leatherStock=BookCoverPasteRollerMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then BookCoverPasteRollerMaker.silverStock=BookCoverPasteRollerMaker.silverStock-d.silverCost*qty end; if d.goldCost then BookCoverPasteRollerMaker.goldStock=BookCoverPasteRollerMaker.goldStock-d.goldCost*qty end; if d.jewelCost then BookCoverPasteRollerMaker.jewelStock=BookCoverPasteRollerMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then BookCoverPasteRollerMaker.pearlStock=BookCoverPasteRollerMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if BookCoverPasteRollerMaker.maker then t=math.max(1,t-math.floor(BookCoverPasteRollerMaker.maker.skill/13)) end; table.insert(BookCoverPasteRollerMaker.activeMaking,{id="bookcoverpasteroller_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function BookCoverPasteRollerMaker.completeMaking(m) local q=1.0+(BookCoverPasteRollerMaker.getQualityBonus()/100); if BookCoverPasteRollerMaker.maker then q=q+(BookCoverPasteRollerMaker.maker.skill/140) end; q=math.min(2.5,q); BookCoverPasteRollerMaker.productStock[m.productType]=(BookCoverPasteRollerMaker.productStock[m.productType] or 0)+m.quantity; BookCoverPasteRollerMaker.totalProducts=BookCoverPasteRollerMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if BookCoverPasteRollerMaker.maker then BookCoverPasteRollerMaker.maker.itemsMade=BookCoverPasteRollerMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then BookCoverPasteRollerMaker.maker.skill=math.min(100,BookCoverPasteRollerMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Valj izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"bookcoverpasteroller.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function BookCoverPasteRollerMaker.update(dt) if not _G.state then return end; BookCoverPasteRollerMaker.dayTimer=BookCoverPasteRollerMaker.dayTimer+dt; if BookCoverPasteRollerMaker.dayTimer>=30 then BookCoverPasteRollerMaker.dayTimer=0; for i=#BookCoverPasteRollerMaker.activeMaking,1,-1 do local m=BookCoverPasteRollerMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then BookCoverPasteRollerMaker.completeMaking(m); table.remove(BookCoverPasteRollerMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(BookCoverPasteRollerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if BookCoverPasteRollerMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
